-- ALTER MATERIALIZED VIEW SET / UNSET
-- https://docs.snowflake.com/en/sql-reference/sql/alter-materialized-view

ALTER MATERIALIZED VIEW mv1 UNSET COMMENT;

ALTER MATERIALIZED VIEW mv1 UNSET SECURE;

ALTER MATERIALIZED VIEW mv1 UNSET TAG my_tag;

ALTER MATERIALIZED VIEW mv1 UNSET TAG tag1, tag2, tag3;

ALTER MATERIALIZED VIEW mv1 UNSET CONTACT STEWARD;

ALTER MATERIALIZED VIEW mv1 UNSET DATA_METRIC_SCHEDULE;

ALTER MATERIALIZED VIEW mv1 SET DATA_METRIC_SCHEDULE = '5 MINUTE';

ALTER MATERIALIZED VIEW mv1 SET CONTACT STEWARD = my_contact;

ALTER MATERIALIZED VIEW mv1 SET CONTACT STEWARD = my_contact, SUPPORT = support_contact;

ALTER MATERIALIZED VIEW mv1 SET SECURE COMMENT = 'both at once';

ALTER MATERIALIZED VIEW mv1 SET COMMENT = 'just a comment';

ALTER MATERIALIZED VIEW mv1 SET TAG my_tag = 'my value';
